import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { CreateSurveyInput } from '@bapp/domain';
import { InMemorySurveyRepository } from '../in-memory-survey-repository';
import { InMemoryLocationRepository } from '../in-memory-location-repository';
import { InMemorySurveyorRepository } from '../in-memory-surveyor-repository';
import { InMemoryObservationRepository } from '../in-memory-observation-repository';

// Codes are now generated by the service and passed into create(); the repo no
// longer invents them. This helper supplies unique codes so tests can focus on
// persistence behaviour without hand-writing codes at every call site.
let codeSeq = 0;
function create(
  repo: InMemorySurveyRepository,
  input: Omit<Partial<CreateSurveyInput>, never> = {},
) {
  codeSeq += 1;
  return repo.create({
    adminCode: `admin${codeSeq}`,
    surveyorCode: `surv${codeSeq}`,
    ...input,
  });
}

describe('InMemorySurveyRepository', () => {
  let repo: InMemorySurveyRepository;

  beforeEach(() => {
    repo = new InMemorySurveyRepository();
  });

  describe('create', () => {
    it('creates a survey with defaults', async () => {
      const survey = await create(repo, { adminCode: 'aaa111', surveyorCode: 'bbb222' });
      expect(survey.id).toBeDefined();
      // Codes are passed through from the input, not invented by the repo.
      expect(survey.adminCode).toBe('aaa111');
      expect(survey.surveyorCode).toBe('bbb222');
      expect(survey.status).toBe('draft');
      expect(survey.name).toBeNull();
      expect(survey.startWeather).toEqual({});
      expect(survey.endWeather).toEqual({});
      expect(survey.data).toEqual({});
      expect(survey.createdAt).toBeInstanceOf(Date);
    });

    it('creates a survey with provided fields', async () => {
      const date = new Date('2026-06-15');
      const survey = await create(repo, {
        name: 'Bat Survey 1',
        postcode: 'SW1A 1AA',
        date,
        status: 'active',
        startWeather: { temperature: '15', wind: '15', cloudCover: '15', humidity: '15', rain: 'yes' },
        endWeather: { temperature: '15', wind: '15', cloudCover: '15', humidity: '15', rain: 'yes' },
      });
      expect(survey.name).toBe('Bat Survey 1');
      expect(survey.postcode).toBe('SW1A 1AA');
      expect(survey.status).toBe('active');
      expect(survey.startWeather).toEqual({ temperature: '15', wind: '15', cloudCover: '15', humidity: '15', rain: 'yes' });
      expect(survey.endWeather).toEqual({ temperature: '15', wind: '15', cloudCover: '15', humidity: '15', rain: 'yes' });
    });

    it('generates unique IDs', async () => {
      const s1 = await create(repo);
      const s2 = await create(repo);
      expect(s1.id).not.toBe(s2.id);
    });
  });

  describe('findById', () => {
    it('returns the survey by ID', async () => {
      const created = await create(repo, { name: 'Test' });
      const found = await repo.findById(created.id);
      expect(found).not.toBeNull();
      expect(found!.name).toBe('Test');
    });

    it('returns null for unknown ID', async () => {
      expect(await repo.findById('nonexistent')).toBeNull();
    });

    it('returns a clone (not a reference)', async () => {
      const created = await create(repo, { name: 'Original' });
      const found = await repo.findById(created.id);
      found!.name = 'Mutated';
      const foundAgain = await repo.findById(created.id);
      expect(foundAgain!.name).toBe('Original');
    });
  });

  describe('findByAdminCode', () => {
    it('finds survey by admin code', async () => {
      const created = await create(repo, { name: 'Admin Test' });
      const found = await repo.findByAdminCode(created.adminCode);
      expect(found).not.toBeNull();
      expect(found!.id).toBe(created.id);
    });

    it('returns null for unknown code', async () => {
      expect(await repo.findByAdminCode('badcode')).toBeNull();
    });
  });

  describe('findBySurveyorCode', () => {
    it('finds survey by surveyor code', async () => {
      const created = await create(repo, { name: 'Surveyor Test' });
      const found = await repo.findBySurveyorCode(created.surveyorCode);
      expect(found).not.toBeNull();
      expect(found!.id).toBe(created.id);
    });

    it('returns null for unknown code', async () => {
      expect(await repo.findBySurveyorCode('badcode')).toBeNull();
    });
  });

  describe('update', () => {
    it('updates specified fields', async () => {
      const created = await create(repo, { name: 'Old' });
      const updated = await repo.update(created.id, { name: 'New', status: 'active' });
      expect(updated.name).toBe('New');
      expect(updated.status).toBe('active');
    });

    it('sets fields to null', async () => {
      const created = await create(repo, { name: 'Has Name' });
      const updated = await repo.update(created.id, { name: null });
      expect(updated.name).toBeNull();
    });

    it('updates updatedAt timestamp', async () => {
      const created = await create(repo);
      const updated = await repo.update(created.id, { name: 'Changed' });
      expect(new Date(updated.updatedAt).getTime()).toBeGreaterThanOrEqual(
        new Date(created.updatedAt).getTime()
      );
    });

    it('throws for unknown ID', async () => {
      await expect(repo.update('nonexistent', { name: 'X' })).rejects.toThrow();
    });
  });

  describe('delete', () => {
    it('removes the survey', async () => {
      const created = await create(repo);
      await repo.delete(created.id);
      expect(await repo.findById(created.id)).toBeNull();
    });
  });

  describe('subscribeById', () => {
    it('fires immediately with current value', async () => {
      const created = await create(repo, { name: 'Sub Test' });
      const callback = vi.fn();
      repo.subscribeById(created.id, callback);
      expect(callback).toHaveBeenCalledTimes(1);
      expect(callback.mock.calls[0][0]?.name).toBe('Sub Test');
    });

    it('fires null for nonexistent ID', () => {
      const callback = vi.fn();
      repo.subscribeById('nonexistent', callback);
      expect(callback).toHaveBeenCalledWith(null);
    });

    it('fires on update', async () => {
      const created = await create(repo, { name: 'Before' });
      const callback = vi.fn();
      repo.subscribeById(created.id, callback);
      await repo.update(created.id, { name: 'After' });
      expect(callback).toHaveBeenCalledTimes(2);
      expect(callback.mock.calls[1][0]?.name).toBe('After');
    });

    it('fires null on delete', async () => {
      const created = await create(repo);
      const callback = vi.fn();
      repo.subscribeById(created.id, callback);
      await repo.delete(created.id);
      expect(callback).toHaveBeenCalledTimes(2);
      expect(callback.mock.calls[1][0]).toBeNull();
    });

    it('stops firing after unsubscribe', async () => {
      const created = await create(repo);
      const callback = vi.fn();
      const unsub = repo.subscribeById(created.id, callback);
      unsub();
      await repo.update(created.id, { name: 'Changed' });
      expect(callback).toHaveBeenCalledTimes(1); // only the initial call
    });
  });

  describe('getSurveyContext', () => {
    it('returns the full survey context', async () => {
      const locationRepo = new InMemoryLocationRepository();
      const surveyorRepo = new InMemorySurveyorRepository();
      const observationRepo = new InMemoryObservationRepository();
      const repoWithContext = new InMemorySurveyRepository(locationRepo, surveyorRepo, observationRepo);

      const survey = await create(repoWithContext, { name: 'Context Test' });
      const loc = await locationRepo.create({ surveyId: survey.id, name: 'Point A' });
      const surveyor = await surveyorRepo.create({ surveyId: survey.id, name: 'Alice' });
      await observationRepo.create({ surveyId: survey.id, locationId: loc.id, surveyorId: surveyor.id, species: 'Pipistrelle' });
      await observationRepo.create({ surveyId: survey.id, locationId: loc.id, surveyorId: surveyor.id, species: 'Noctule' });

      const context = await repoWithContext.getSurveyContext(survey.id);
      expect(context.survey.id).toBe(survey.id);
      expect(context.locations).toHaveLength(1);
      expect(context.surveyors).toHaveLength(1);
      expect(context.observations).toHaveLength(2);
    });

    it('returns empty arrays when no child entities exist', async () => {
      const locationRepo = new InMemoryLocationRepository();
      const surveyorRepo = new InMemorySurveyorRepository();
      const observationRepo = new InMemoryObservationRepository();
      const repoWithContext = new InMemorySurveyRepository(locationRepo, surveyorRepo, observationRepo);

      const survey = await create(repoWithContext);
      const context = await repoWithContext.getSurveyContext(survey.id);
      expect(context.survey.id).toBe(survey.id);
      expect(context.locations).toEqual([]);
      expect(context.surveyors).toEqual([]);
      expect(context.observations).toEqual([]);
    });

    it('throws for unknown survey ID', async () => {
      const locationRepo = new InMemoryLocationRepository();
      const surveyorRepo = new InMemorySurveyorRepository();
      const observationRepo = new InMemoryObservationRepository();
      const repoWithContext = new InMemorySurveyRepository(locationRepo, surveyorRepo, observationRepo);

      await expect(repoWithContext.getSurveyContext('nonexistent')).rejects.toThrow();
    });

    it('throws when child repositories not provided', async () => {
      const repoWithoutContext = new InMemorySurveyRepository();
      const survey = await create(repoWithoutContext);
      await expect(repoWithoutContext.getSurveyContext(survey.id)).rejects.toThrow();
    });

    it('only includes entities for the requested survey', async () => {
      const locationRepo = new InMemoryLocationRepository();
      const surveyorRepo = new InMemorySurveyorRepository();
      const observationRepo = new InMemoryObservationRepository();
      const repoWithContext = new InMemorySurveyRepository(locationRepo, surveyorRepo, observationRepo);

      const survey1 = await create(repoWithContext, { name: 'Survey 1' });
      const survey2 = await create(repoWithContext, { name: 'Survey 2' });
      await locationRepo.create({ surveyId: survey1.id, name: 'A' });
      await locationRepo.create({ surveyId: survey2.id, name: 'B' });
      await surveyorRepo.create({ surveyId: survey1.id, name: 'Alice' });
      await surveyorRepo.create({ surveyId: survey2.id, name: 'Bob' });

      const context = await repoWithContext.getSurveyContext(survey1.id);
      expect(context.locations).toHaveLength(1);
      expect(context.locations[0].name).toBe('A');
      expect(context.surveyors).toHaveLength(1);
      expect(context.surveyors[0].name).toBe('Alice');
    });
  });
});
